-- 2. role_has_permissions / employee_has_roles: dựng lại theo khuôn cũ từ bak_rbac_*. Xoá TRƯỚC bảng phụ rbac_old_* /
--    rbac_new_* còn sót (DDL dừng giữa chừng): RENAME chuyển tên khoá ngoại gốc sang rbac_old_*, để lại thì ADD CONSTRAINT trùng tên.
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS rbac_old_role_has_permissions, rbac_old_employee_has_roles, rbac_new_role_has_permissions, rbac_new_employee_has_roles;
DROP TABLE IF EXISTS `role_has_permissions`;
CREATE TABLE `role_has_permissions` LIKE `bak_rbac_role_has_permissions`;
INSERT INTO `role_has_permissions` (`permission_id`, `role_id`, `company_id`, `scope`) SELECT `permission_id`, `role_id`, `company_id`, `scope` FROM `bak_rbac_role_has_permissions`;
ALTER TABLE `role_has_permissions` ADD CONSTRAINT `role_has_permissions_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`);
DROP TABLE IF EXISTS `employee_has_roles`;
